baselineExtracted.checked:
:is(.uif-checkbox, .checkbox):checked::after,
:is(.uif-checkbox, .checkbox).is-checked::after {
  content: "";
  inline-size: 0.75em;
  block-size: 0.75em;
  background-color: currentColor;
  -webkit-mask-image: url("../../assets/icons/checkmark.svg");
  mask-image: url("../../assets/icons/checkmark.svg");
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
}

baselineExtracted.mixed:
:is(.uif-checkbox, .checkbox):indeterminate::after,
:is(.uif-checkbox, .checkbox).is-indeterminate::after {
  inline-size: 0.75rem;
  block-size: var(--size-border-200);
  border-radius: var(--size-radius-full);
  background: currentColor;
}

baselineExtracted.mask:
:is(.uif-icon, .icon) {
  display: inline-block;
  inline-size: 1em;
  block-size: 1em;
  inline-size: 1lh;
  block-size: 1lh;
  line-height: inherit;
  background-color: currentColor;
  -webkit-mask-image: var(--uif-icon-src);
  mask-image: var(--uif-icon-src);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  vertical-align: middle;
}

